def solve(assignment, domains, constraints):
    if len(assignment) == len(domains):
        return assignment
    # Most-constrained variable first: fail fast, prune more.
    var = min((v for v in domains if v not in assignment),
              key=lambda v: len(domains[v]))
    for value in domains[var]:
        if all(c(assignment, var, value) for c in constraints):
            assignment[var] = value
            result = solve(assignment, domains, constraints)
            if result:
                return result
            del assignment[var]          # UNDO - this is the backtrack
        # else: pruned without recursing at all
    return None
